  + validity_year : int
}

class Trip {
  + time : time
  + date : date
}

class Invoice {
  + month : int
  + total_amount : double
  + discount : float
}

class Customer {
  + home_address : string
  + office_address : string
  + working_hours : string
}

class MENSO_Card {
}

class TicketMachine {
}

class Payment {
}

Bus "0..*" -- "1" Line : assigned to
Line "1" -- "1..*" Trajectory : groups
Trajectory "0..*" -- "0..1" Approval : undergoes
Approval "0..*" -- "1" TownAuthority : issued by
Line "1" -- "0..*" Trip : recorded in
Trip "1" -- "1" TicketMachine : registered by
Trip "1" -- "1" MENSO_Card : uses
Trip "0..*" -- "1" Customer : performed by
Customer "1" -- "*" Invoice : receives
Customer "1" -- "1" MENSO_Card : owns
Invoice "0..*" -- "1" Customer : paid by
Invoice "1" -- "0..*" Payment : settled by

@enduml

